import math
from functools import reduce

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_of_range(start, end):
    if start > end:
        return 1
    return reduce(lcm, range(start, end + 1))

N_values = [3, 4]
K_limit = 50

results = {}

for n in N_values:
    results[n] = []
    print(f"--- Results for n = {n} ---")

    for k in range(1, K_limit + 1):
        # x_k = lcm(k, k+1, ..., k+n-1)
        x_k = lcm_of_range(k, k + n - 1)

        # x_{k+1} = lcm(k+1, k+2, ..., k+n)
        x_k_plus_1 = lcm_of_range(k + 1, k + n)

        ratio = x_k_plus_1 / x_k

        # Store (k, x_k, x_{k+1}, ratio)
        results[n].append((k, x_k, x_k_plus_1, ratio))

        # Optional: Print a few samples for quick verification
        if k <= 3 or k == 48:
            print(f"k={k}: x_k = {x_k}, x_{k+1} = {x_k_plus_1}, Ratio = {ratio}")

# Check the trend (if x_{k+1} > x_k eventually)
def check_weakly_increasing(data):
    if not data:
        return "Insufficient data"

    # Check the last 5 computed ratios
    last_ratios = [d[3] for d in data[-5:]]

    # Check if all ratios are >= 1 (weakly increasing)
    # We are looking for eventual strict increase, which implies ratios > 1 eventually.

    # Check if the sequence is monotonically increasing for the last few points (allowing for floating point errors)
    is_eventually_increasing = all(r >= 1.0 - 1e-9 for r in last_ratios)

    # Check for strict increase in the last 5 points
    is_strictly_increasing = all(r > 1.0 + 1e-9 for r in data[-5:])

    return {
        "is_weakly_increasing_in_sample": is_eventually_increasing,
        "is_strictly_increasing_in_sample": is_strictly_increasing
    }

