import math

def lcm(a, b):
    """Computes the least common multiple of two numbers."""
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def compute_x_k(k, n):
    """Computes x_k = lcm(k, k+1, ..., k+n-1)."""
    if n == 0:
        return 1

    current_lcm = k
    for i in range(k + 1, k + n):
        current_lcm = lcm(current_lcm, i)
    return current_lcm

def check_weakly_increasing(n, max_k=1000):
    """Checks if x_{k+1} >= x_k for k=1 up to max_k."""
    print(f"\n--- Checking n={n} up to k={max_k} ---")

    # Calculate x_1
    try:
        x_k_current = compute_x_k(1, n)
    except RecursionError:
        print(f"Error calculating x_1 for n={n}. The LCM is too large or computation failed.")
        return False

    for k in range(1, max_k):
        # Calculate x_{k+1}
        x_k_next = compute_x_k(k + 1, n)

        # Check the condition
        if x_k_next < x_k_current:
            print(f"FAILURE found at k={k}: x_{k+1} ({x_k_next}) < x_k ({x_k_current})")
            return False

        # Update for next iteration
        x_k_current = x_k_next

        # Optional: Print a few checks to demonstrate progress
        if k in [10, 100, 999]:
             print(f"k={k}: x_{k+1}/x_k = {x_k_next / (x_k_current * (x_k_next / x_k_current))} (Ratio Check, actual ratio check is cleaner)")
             print(f"k={k}: Ratio x_{k+1}/x_k = {x_k_next / x_k_current}")


    print(f"SUCCESS: x_{k+1} >= x_k held true for all k=1 to {max_k-1} for n={n}.")
    return True

# Perform the requested checks
check_weakly_increasing(n=1, max_k=1000)
